def anti_shuffle(s):
    result = []
    word = []
    for c in s:
        if c != ' ':
            word.append(c)
        else:
            if word:
                sorted_word = ''.join(sorted(word))
                result.append(sorted_word)
                word = []
            result.append(' ')
    if word:
        sorted_word = ''.join(sorted(word))
        result.append(sorted_word)
    return ''.join(result)


