def move_one_ball(arr):
    if not arr:
        return True
    n = len(arr)
    # Check for each possible right shift (0 to n-1)
    for shift in range(n):
        # Create shifted array by moving last 'shift' elements to the front
        shifted = arr[-shift:] + arr[:-shift] if shift > 0 else arr
        # Check if shifted array is non-decreasing
        if all(shifted[i] <= shifted[i+1] for i in range(n-1)):
            return True
    return False


