def parse_nested_parens(paren_string: str) -> List[int]:
    """
    Input: a string of well-formed groups of parentheses separated by single spaces.
    Output: a list of integers representing the maximum nesting depth per group.

    No loops or recursion are used.
    """
    # Split input into groups
    groups = paren_string.split(' ')

    # For each group, compute the max depth using accumulate over +1 for '(' and -1 for ')'
    # Using map and max with no explicit loops
    from itertools import accumulate

    def max_depth(group: str) -> int:
        levels = list(accumulate(1 if c == '(' else -1 for c in group))
