from typing import List, Tuple

def parse_music(music_string: str) -> Tuple[List[int], str]:
    beats_map = {'o': 4, 'o|': 2, '.|': 1}
    notes = music_string.split()
    beats = list(map(beats_map.get, notes))

    # Count occurrences without loops or recursion, by direct count() calls
    counts = {
        'o': notes.count('o'),
        'o|': notes.count('o|'),
        '.|': notes.count('.|')
    }

    # Determine most common note, tie broken by longest beat length
    # If all counts are zero (empty input), return empty list and empty string
    if all(count == 0 for count in counts.values()):
        return [], ''

    candidates = [('o', counts['o'], beats_map['o']),
                  ('o|', counts['o|'], beats_map['o|']),
                  ('.|', counts['.|'], beats_map['.|'])]
    # max by count, then by beat length
    most_common = max(candidates, key=lambda x: (x[1], x[2]))[0]

    return beats, most_common


