def monotonic(l):
    if isinstance(l, str):
        # For strings: return False if duplicates, else (True, string) if monotonic ascending or descending
        if len(set(l)) != len(l):
            return False
        # Check strictly ascending
        if all(l[i] < l[i+1] for i in range(len(l)-1)):
            return True, l
        # Check strictly descending
        if all(l[i] > l[i+1] for i in range(len(l)-1)):
            return True, l
        return False
    else:
        # For lists: return True if monotonic non-decreasing or non-increasing (duplicates allowed), else False
        # Monotonic increasing means l[i] <= l[i+1]
        if all(l[i] <= l[i+1] for i in range(len(l)-1)):
            return True
        # Monotonic decreasing means l[i] >= l[i+1]
        if all(l[i] >= l[i+1] for i in range(len(l)-1)):
            return True
        return False


