from collections import Counter

def search(lst):
    freq = Counter(lst)
    # Filter values where frequency >= value (for numbers) or use lex order for strings
    # Since we want greatest integer > 0 with freq >= value for numbers,
    # and for strings, greatest string (lex order) that appears at least once

    # Determine if list is numeric or string by type of first element
    first = lst[0]
    if isinstance(first, int):
        # Filter integers greater than zero and freq >= value
        candidates = [x for x in freq if isinstance(x, int) and x > 0 and freq[x] >= x]
        return max(candidates) if candidates else -1
    else:
        # For strings, return the lex greatest string that appears at least once
        candidates = [x for x in freq if isinstance(x, str)]
        return max(candidates) if candidates else -1


