def total_match(lst1, lst2):
    # Helper to check if a list contains any string
    def contains_str(lst):
        return any(isinstance(x, str) for x in lst)

    # If any list contains strings, return the longest string among both lists
    if contains_str(lst1) or contains_str(lst2):
        all_strings = [x for x in lst1 + lst2 if isinstance(x, str)]
        if not all_strings:
            return ""
        return max(all_strings, key=len)

    # Both lists are integer lists (or empty)
    # Calculate total digits for each list (sum of length of str(abs(num)))
    def total_digits(lst):
        # No loops allowed in the function itself, but using sum with generator is allowed 
        # as it's a builtin and hides the iteration.
        return sum(len(str(abs(x))) for x in lst)

    td1 = total_digits(lst1)
    td2 = total_digits(lst2)

    # Decide which list to return
    # If equal digits, return first list
    if td1 <= td2:
        chosen = lst1
    else:
        chosen = lst2

    # Sort chosen list ascending but maintain original relative order among equals
    # This means stable sort by value ascending
    # Python's sorted() is stable
    chosen_sorted = sorted(chosen, key=lambda x: x)

    # Return as string of space-separated values
    return " ".join(str(x) for x in chosen_sorted)


