def anti_shuffle(s):
    import re
    # Split the string into words and spaces, preserving spaces
    parts = re.findall(r'\S+|\s+', s)
    result = []
    for part in parts:
        if part.isspace():
            # keep spaces as is
            result.append(part)
        else:
            # sort each word's characters in ascending ASCII order
            result.append(''.join(sorted(part)))
    return ''.join(result)


