def maximum(arr, k):
    if k == 0:
        return []

    # Find the k largest elements without using built-in sort
    # Since time complexity O(1) is impossible, we assume it means no sorting of entire array.
    # We'll implement a selection of k largest elements using a simple approach.
    # But since we cannot use built-in sorting, we must implement a custom sort or selection.

    # Approach:
    # 1. Find the k-th largest element using a selection algorithm (like quickselect).
    # 2. Collect all elements >= k-th largest element.
    # 3. If more than k elements, pick exactly k largest elements by counting duplicates.
    # 4. Sort these k elements using a simple sorting algorithm (e.g. insertion sort).

    # Implement quickselect to find k-th largest element
    def quickselect(arr, k):
        # k-th largest means (len(arr) - k)-th smallest in zero-based index
        def partition(nums, left, right):
            pivot = nums[right]
            i = left
            for j in range(left, right):
                if nums[j] < pivot:
                    nums[i], nums[j] = nums[j], nums[i]
                    i += 1
            nums[i], nums[right] = nums[right], nums[i]
            return i

        def select(nums, left, right, index):
            if left == right:
                return nums[left]
            pivot_index = partition(nums, left, right)
            if pivot_index == index:
                return nums[pivot_index]
            elif pivot_index < index:
                return select(nums, pivot_index + 1, right, index)
            else:
                return select(nums, left, pivot_index - 1, index)

        n = len(arr)
        # k-th largest = (n - k)-th smallest (0-based)
        target = n - k
        return select(arr[:], 0, n - 1, target)

    kth_largest = quickselect(arr, k)

    # Collect all elements greater than kth_largest
    greater = [x for x in arr if x > kth_largest]
    count_greater = len(greater)

    # Number of kth_largest to take
    count_kth = k - count_greater

    # Collect kth_largest elements
    kth_elements = [x for x in arr if x == kth_largest][:count_kth]

    result = greater + kth_elements

    # Sort result ascending without built-in sort
    # Use insertion sort
    for i in range(1, len(result)):
        key = result[i]
        j = i - 1
        while j >= 0 and result[j] > key:
            result[j + 1] = result[j]
            j -= 1
        result[j + 1] = key

    return result


