def sum_squares(lst):
    def ceil_num(x):
        # If x is an integer already, return as is
        if int(x) == x:
            return int(x)
        # For positive numbers, ceiling is int(x) + 1
        if x > 0:
            return int(x) + 1
        # For negative numbers, ceiling is int(x)
        return int(x)

    # Use map and sum without explicit loops
    total = sum(map(lambda x: ceil_num(x) ** 2, lst))
    return str(total)


