def order_by_points(nums):
    if not nums:
        return []
    # key: (sum of digits), stable sort so original order preserved if sums equal
    def digit_sum(x):
        s = str(x).lstrip('-')
        return sum(map(int, s))
    sorted_nums = sorted(nums, key=digit_sum)
    return ", ".join(str(x) for x in sorted_nums)


