def solve(s):
    if any(c.isalpha() for c in s):
        # If there is any letter, reverse case for letters, keep others as is
        return ''.join(c.swapcase() if c.isalpha() else c for c in s)
    else:
        # No letters, reverse the string of digits and return as string
        return s[::-1]


