def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)
    # Since the array has unique elements, we can find the index of the minimal element
    min_val = min(arr)
    min_idx = arr.index(min_val)

    # Rotate the array so that min_idx is at the front
    rotated = arr[min_idx:] + arr[:min_idx]

    # Check if rotated array is sorted non-decreasingly
    for i in range(n - 1):
        if rotated[i] > rotated[i + 1]:
            return False
    return True


