def parse_nested_parens(text):
    groups = text.split()
    depths = []
    for group in groups:
        current_depth = 0
        max_depth = 0
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                if current_depth > 0:
                    current_depth -= 1
                else:
                    # unbalanced closing paren, ignore decrement to avoid negative depth
                    pass
        depths.append(max_depth)
    return depths


