def triples_sum_to_zero(items):
    items = list(items)
    n = len(items)
    items.sort()
    for i in range(n - 2):
        a = items[i]
        left, right = i + 1, n - 1
        while left < right:
            s = a + items[left] + items[right]
            if s == 0:
                return True
            elif s < 0:
                left += 1
            else:
                right -= 1
    return False


