def move_one_ball(seq):
    if not seq:
        return True
    n = len(seq)
    # Count how many places the sequence decreases when traversed circularly
    decreases = 0
    for i in range(n):
        if seq[i] > seq[(i + 1) % n]:
            decreases += 1
            # More than one decrease means it cannot be made sorted by rotation
            if decreases > 1:
                return False
    return True


