def order_by_points(items):
    def digit_score(n):
        s = str(abs(n))
        digits = list(map(int, s))
        if n < 0:
            # First digit contributes negatively
            return -digits[0] + sum(digits[1:])
        else:
            return sum(digits)
    return sorted(items, key=digit_score)


