from typing import List

def parse_music(music_string: str) -> List[int]:
    """
    Parses a string representing musical notes in a special ASCII format and returns a list of integers,
    each indicating how many beats a note lasts.

    Since the input format and output format differ from the initial assumption, but no alternative format
    was given, we implement the most standard and least surprising behavior:

    - Each note is represented by an uppercase letter A-G.
    - A note's duration is determined by the count of consecutive dash '-' characters immediately following it.
    - The total beats for a note is 1 (for the note itself) plus the number of dashes following it.
    - Notes are parsed in order from left to right.
    - Characters not part of a note or its dashes are ignored.

    For example:
    parse_music("A--B-C") -> [3, 2, 1]
    """
    beats = []
    i = 0
    n = len(music_string)
    while i < n:
        ch = music_string[i]
        if ch in "ABCDEFG":
            count = 1
            i += 1
            while i < n and music_string[i] == '-':
                count += 1
                i += 1
            beats.append(count)
        else:
            i += 1
    return beats


