def order_by_points(nums):
    def digit_sum(n):
        s = str(n)
        if s[0] == '-':
            # first digit negative, rest positive
            first_digit = -int(s[1])
            rest_digits = map(int, s[2:])
            return first_digit + sum(rest_digits)
        else:
            return sum(map(int, s))
    return sorted(nums, key=lambda x: digit_sum(x))


