def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)
    # Since elements are unique, the array can be sorted by right shifts
    # if it is a rotated sorted array.
    # Check how many places where arr[i] > arr[i+1]
    # If there is more than one such place, it can't be sorted by rotation.

    count_breaks = 0
    for i in range(n - 1):
        if arr[i] > arr[i + 1]:
            count_breaks += 1
            if count_breaks > 1:
                return False

    # Also check if the last element > first element after rotation
    # Actually, if count_breaks == 0, array is already sorted => True
    # If count_breaks == 1, check if last element <= first element
    # Because if arr[-1] > arr[0], rotation won't fix the order.

    if count_breaks == 0:
        return True
    elif count_breaks == 1:
        return arr[-1] <= arr[0]
    else:
        return False


