def order_by_points(nums):
    def digit_sum(n):
        s = str(n)
        if s[0] == '-':
            # First digit after '-' is negative
            first_digit = -int(s[1])
            # rest digits positive
            rest = s[2:]
            rest_sum = sum(int(d) for d in rest)
            return first_digit + rest_sum
        else:
            return sum(int(d) for d in s)
    return sorted(nums, key=digit_sum)


