def mean_absolute_deviation(numbers: List[float]) -> float:
    if not numbers:
        # No values to calculate mean absolute deviation, return 0.0 or raise an error
        # Here we choose to return 0.0 to avoid ZeroDivisionError
        return 0.0
    mean = sum(numbers) / len(numbers)
    return sum(abs(x - mean) for x in numbers) / len(numbers)


