def digits(n):
    """Given an integer n, return the product of the odd digits.
    Uses the absolute value of n.
    Returns 1 if no odd digits are found."""
    n = abs(n)
    product = 1
    found_odd = False
    while n > 0:
        d = n % 10
        if d % 2 == 1:
            product *= d
            found_odd = True
        n //= 10
    return product if found_odd else 1


