def will_it_fly(q, w):
    can_fly = q.get('can_fly', False)
    weight = q.get('weight', 0)
    okay = q.get('okay', True)

    if not can_fly:
        return False

    if isinstance(weight, (list, tuple)):
        # q must be a palindrome
        if list(q) != list(reversed(q)):
            return False
        total_weight = sum(weight)
        if total_weight > w:
            return False
        # "okay" condition is not automatic for sequences, must be checked explicitly:
        if not okay:
            return False
        return True
    else:
        # weight is a single number
        if weight > w:
            return False
        return bool(okay)


