def select_words(s, n):
    vowels = set("aeiouAEIOU")
    if not s:
        return []
    result = []
    length = len(s)
    for start in range(length):
        non_vowel_count = 0
        for end in range(start, length):
            c = s[end]
            if c.isalpha() and c not in vowels:
                non_vowel_count += 1
            if non_vowel_count == n:
                result.append(s[start:end+1])
            elif non_vowel_count > n:
                break
    return result


