def order_by_points(nums):
    def digit_sum(n):
        s = str(n)
        total = 0
        if s[0] == '-':
            # Leading minus sign makes first digit negative
            total -= int(s[1])
            # Add the rest of the digits positively
            for d in s[2:]:
                total += int(d)
        else:
            # All digits positive
            for d in s:
                total += int(d)
        return total

    return sorted(nums, key=lambda x: digit_sum(x))


