from typing import List

def parse_music(music_string: str) -> List[int]:
    notes = music_string.split()
    result = []
    for note in notes:
        if note == 'o':
            result.append(4)
        elif note == 'o|':
            result.append(2)
        elif note == '.|':
            result.append(1)
        else:
            # If any unknown note appears, treat it as 1 beat (safe fallback)
            result.append(1)
    return result


