def anti_shuffle(s):
    import re

    # Split string into words and spaces preserving their order
    parts = re.findall(r'\S+|\s+', s)

    result = []
    for part in parts:
        if part.isspace():
            # Preserve spaces as is
            result.append(part)
        else:
            # Sort all characters in the word by ASCII
            sorted_word = ''.join(sorted(part))
