def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)
    # Check if arr is already sorted non-decreasing
    if all(arr[i] <= arr[i+1] for i in range(n-1)):
        return True

    # Try all possible right shifts
    # Right shift by k means last k elements move to front
    for k in range(1, n):
        # Construct shifted array
        shifted = arr[-k:] + arr[:-k]
        if all(shifted[i] <= shifted[i+1] for i in range(n-1)):
            return True

    return False


