def sum_squares(lst):
    total = 0
    for i, val in enumerate(lst):
        if i % 3 == 0:
            # square if multiple of 3 (including those multiple of both 3 and 4)
            total += val ** 2
        elif i % 4 == 0:
            # cube if multiple of 4 but not 3
            total += val ** 3
        else:
            total += val
    return total


