def parse_music(music_string: str) -> List[int]:
    notes = music_string.split()
    durations = []
    for note in notes:
        if note == 'o':
            durations.append(1)
        elif note == 'o|':
            durations.append(4)
        elif note == '.|':
            durations.append(2)
        else:
            # If an unknown note is encountered, could raise an error or ignore.
            # Here we ignore it.
            pass
    return durations


