def anti_shuffle(s):
    import re
    parts = re.split(r'(\s+)', s)
    result = []
    for part in parts:
        if part.isspace() or part == '':
            result.append(part)
        else:
            # Extract trailing non-alphabetic characters
            i = len(part)
            while i > 0 and not part[i-1].isalpha():
                i -= 1
            word, trailing = part[:i], part[i:]
            sorted_word = ''.join(sorted(word))
            result.append(sorted_word + trailing)
    return ''.join(result)


