def dif_Square(n: int) -> bool:
    # n = a^2 - b^2 = (a-b)(a+b)
    # Let x = a-b, y = a+b, then n = x*y
    # a = (x+y)/2, b = (y-x)/2 must be integers => (x+y) and (y-x) both even
    # => x and y have the same parity (both even or both odd)

    # So n can be represented as difference of squares iff
    # n can be factored into two integers x,y of the same parity

    # For n=0, 0 = 0^2 - 0^2, so True
    if n == 0:
        return True

    # Iterate through divisors of n (including negative)
    # but since we only need to find one such pair, we can just check the positive divisors and consider their negatives accordingly.

    abs_n = abs(n)
    # For each divisor d of abs_n, check if d and n//d have the same parity
    # Because if n = d * (n//d), and d and n//d have same parity, then True

    # We can check all divisors from 1 to sqrt(abs_n)
    from math import isqrt

    for d in range(1, isqrt(abs_n) + 1):
        if abs_n % d == 0:
            q = abs_n // d
            # Check pairs (d, q) and (-d, -q) for parity
            # Since parity depends only on the numbers mod 2, and signs do not affect parity,
            # just check if d and q have the same parity
            if (d % 2) == (q % 2):
                return True
    return False


