def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)

    # Helper to check if a string is palindrome
    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    # If n < 8, next palindrome is n+1
    if n < 8:
        return n + 1

    # If all digits are 9, e.g. 9, 99, 999 -> next palindrome is 1001, 10001, ...
    if all(ch == '9' for ch in s):
        return n + 2  # e.g. 9 -> 11, 99 -> 101, 999 -> 1001

    # Generate the palindrome by mirroring left to right
    half = (length + 1) // 2
    left = s[:half]

    if length % 2 == 0:
        palindrome = left + left[::-1]
    else:
        palindrome = left + left[:-1][::-1]

    if int(palindrome) > n:
        return int(palindrome)

    # Otherwise, increment the left half and mirror again
    left_num = int(left) + 1
    left_str = str(left_num)
    # If increment increases length (e.g. 999 + 1 = 1000)
    if len(left_str) > len(left):
        # For example, 999 -> palindrome length increases by 1
        # Result is 10...01 with length+1 digits
        return int("1" + ("0" * (length - 1)) + "1")

    if length % 2 == 0:
        palindrome = left_str + left_str[::-1]
    else:
        palindrome = left_str + left_str[:-1][::-1]

    return int(palindrome)


