def find_solution(a, b, n):
    # Try all non-negative x starting from 0 upwards
    # Stop when ax > n because y would be negative
    if a == 0 and b == 0:
        return None if n != 0 else ('x = ', 0, ', y = ', 0)
    if a == 0:
        # equation is b*y = n
        if b == 0:
            return None
        if n % b == 0 and n // b >= 0:
            return ('x = ', 0, ', y = ', n // b)
        else:
            return None
    if b == 0:
        # equation is a*x = n
        if n % a == 0 and n // a >= 0:
            return ('x = ', n // a, ', y = ', 0)
        else:
            return None

    max_x = n // a if a > 0 else (n // a if a < 0 else 0)
    # We want smallest non-negative x, so start at 0 and increment
    x = 0
    while True:
        ax = a * x
        if ax > n and a > 0:
            break
        # Solve for y: b*y = n - a*x
        remainder = n - ax
        if b != 0 and remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return ('x = ', x, ', y = ', y)
        x += 1
        # To avoid infinite loop when a <= 0:
        # If a <= 0, x increasing makes ax <= 0 or negative, so if x grows large,
        # ax won't exceed n to stop loop. So limit search by some bound:
        if x > 10**7:
            break
    return None


