def get_total_number_of_sequences(n: int, m: int) -> int:
    # dp[i][x]: number of sequences of length i starting with x
    # The sequences start from any integer in [1..m]
    # and each next element >= 2 * previous element and <= m

    if n == 1:
        return m  # Any single element sequence from 1 to m

    # For n >= 2
    # We'll build dp for length from 1 up to n

    # Initialize dp for length 1
    dp_prev = [1] * (m + 1)  # Index 0 unused, dp_prev[x] = 1 for x in 1..m

    for length in range(2, n + 1):
        dp_cur = [0] * (m + 1)

        # To efficiently compute:
        # dp_cur[x] = sum of dp_prev[y] for all y >= 2*x and y <= m

        # We can precompute suffix sums of dp_prev to quickly sum dp_prev[y] for y >= 2*x

        suffix_sum = [0] * (m + 2)
        for i in range(m, 0, -1):
            suffix_sum[i] = suffix_sum[i + 1] + dp_prev[i]

        for x in range(1, m + 1):
            start = 2 * x
            if start <= m:
                dp_cur[x] = suffix_sum[start]
            else:
                dp_cur[x] = 0

        dp_prev = dp_cur

    # Total sequences of length n are sum over all starting elements 1..m
    return sum(dp_prev[1:m+1])


