def find_Max(arr, start, end):
    if start > end:
        return None
    # If the array is not rotated or only one element
    if arr[start] <= arr[end]:
        return arr[end]
    mid = (start + end) // 2
    # If mid element is greater than next element, mid is max
    if mid < end and arr[mid] > arr[mid + 1]:
        return arr[mid]
    # If mid element is smaller than previous element, previous is max
    if mid > start and arr[mid] < arr[mid - 1]:
        return arr[mid - 1]
    # Decide which side to go
    if arr[mid] > arr[start]:
        return find_Max(arr, mid + 1, end)
    else:
        return find_Max(arr, start, mid - 1)


