def filter_data(students, min_height=None, max_height=None, min_width=None, max_width=None):
    """
    Filters students by height and width conditions.

    Parameters:
    - students: dict mapping student name to (height, width) tuple.
    - min_height: minimum height inclusive (or None to ignore).
    - max_height: maximum height inclusive (or None to ignore).
    - min_width: minimum width inclusive (or None to ignore).
    - max_width: maximum width inclusive (or None to ignore).

    Returns:
    - dict of students passing all specified filters.
    """
    def passes(height, width):
        if min_height is not None and height < min_height:
            return False
        if max_height is not None and height > max_height:
            return False
        if min_width is not None and width < min_width:
            return False
        if max_width is not None and width > max_width:
            return False
        return True

    return {name: (h, w) for name, (h, w) in students.items() if passes(h, w)}


