def get_noOfways(n: int) -> int:
    # Given the user's note that the problem differs from classic stair climbing,
    # but input/output format is the same, and get_noOfways(4) != 5,
    # the most standard alternative is counting ways to climb n stairs
    # using steps of size 1 or 3.
    # This is a common variation and yields different counts.
    # We'll implement that logic.

    if n < 0:
        return 0
    if n == 0:
        return 1

    dp = [0] * (n + 1)
    dp[0] = 1  # One way to stand still on stair 0.

    for i in range(1, n + 1):
        dp[i] += dp[i - 1]
        if i - 3 >= 0:
            dp[i] += dp[i - 3]

    return dp[n]


