def dif_Square(n: int) -> bool:
    # n = a² - b² = (a-b)(a+b)
    # Let x = a-b, y = a+b, then n = x*y
    # a = (x+y)/2, b = (y - x)/2 must be integers
    # So x and y must have the same parity (both even or both odd)
    # For n = 0, a = b, so difference of squares is 0 = 0² - 0² (True)
    if n == 0:
        return True
    abs_n = abs(n)
    # Iterate through all divisors x of abs_n
    # For each divisor x, y = n/x (if divides evenly)
    # Check if x and y have same parity
    # Because x and y are factors of n, and n=x*y
    # For negative n, x and y can be negative, but parity still applies
    # We check all pairs (x, y) such that x*y = n
    # To avoid float division, iterate over divisors of abs_n, and check signs accordingly
    import math

    for x in range(1, int(math.isqrt(abs_n)) + 1):
        if abs_n % x == 0:
            y = abs_n // x
            # Check pairs (x, y) with signs adjusted for n
            # Because n can be negative, either x or y can be negative
            # So check four sign combinations of (x,y) with product n:
            # (x, y), (-x, -y), (x, -y), (-x, y)
            # Only those with product == n are candidates

            pairs = []
            if x * y == n:
                pairs.append((x, y))
            if (-x) * (-y) == n:
                pairs.append((-x, -y))
            if x * (-y) == n:
                pairs.append((x, -y))
            if (-x) * y == n:
                pairs.append((-x, y))

            for (X, Y) in pairs:
                # Check parity: X and Y must be both even or both odd
                if (X % 2) == (Y % 2):
                    return True
    return False


