def next_smallest_palindrome(num: int) -> int:
    s = str(num + 1)
    length = len(s)

    while True:
        # For odd length, middle index
        mid = length // 2
        if length % 2 == 0:
            left = s[:mid]
            pal_candidate = left + left[::-1]
        else:
            left = s[:mid]
            mid_char = s[mid]
            pal_candidate = left + mid_char + left[::-1]

        if int(pal_candidate) >= num + 1:
            return int(pal_candidate)

        # Increment the middle part and rebuild palindrome
        if length % 2 == 0:
            left_num = int(left) + 1
            left = str(left_num)
            # if increment changes length, e.g. 99->100, handle that
            if len(left) > mid:
                length += 1
                s = "1" + "0" * (length - 2) + "1"
            else:
                s = left + left[::-1]
        else:
            middle_num = int(s[mid]) + 1
            if middle_num <= 9:
                s = left + str(middle_num) + left[::-1]
            else:
                # middle digit rolls over to 0, increment left part
                left_num = int(left) + 1
                left = str(left_num)
                if len(left) > mid:
                    length += 1
                    s = "1" + "0" * (length - 2) + "1"
                else:
                    s = left + "0" + left[::-1]


