def find_solution(a, b, n):
    if b == 0:
        # ax = n => x = n/a if divisible
        if a != 0 and n % a == 0:
            x = n // a
            y = 0
            if x >= 0:
                return ('x = ', x, ', y = ', y)
        return 'No solution'
    x = 0
    while True:
        diff = n - a * x
        if b != 0 and diff % b == 0:
            y = diff // b
            if x >= 0:
                return ('x = ', x, ', y = ', y)
        x += 1
        # To avoid infinite loop if no solution:
        # Since x starts at 0 and increases, if a and b are both 0,
        # no solution unless n==0; handled separately.
        # To prevent infinite loop when no solution, stop at some large limit:
        if x > abs(n) + abs(b) + abs(a) + 1000:
            return 'No solution'


