def find_Max(nums):
    if not nums:
        return None
    left, right = 0, len(nums) - 1
    # If the list is not rotated (last element > first element), max is last element
    if nums[left] < nums[right]:
        return nums[right]
    # Binary search for the pivot point (max element)
    while left < right:
        mid = (left + right) // 2
        if nums[mid] > nums[right]:
            left = mid + 1
        else:
            right = mid
    # left is now the index of the smallest element, so max is element before it
    return nums[left - 1]


