def odd_length_sum(arr):
    n = len(arr)
    total = 0
    for i in range(n):
        # Total subarrays including arr[i]
        total_subarrays = (i + 1) * (n - i)
        # Count of odd-length subarrays including arr[i]
        odd_count = (total_subarrays + 1) // 2
        total += arr[i] * odd_count
    return total


