def substract_elements(a, b):
    if isinstance(a, (list, tuple)) and isinstance(b, (list, tuple)):
        # Both are sequences: subtract element-wise recursively
        if len(a) != len(b):
            raise ValueError("Input collections must have the same shape")
        return type(a)(substract_elements(x, y) for x, y in zip(a, b))
    elif isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return a - b
    else:
        # Mismatched types or unsupported types
        raise TypeError("Both inputs must have the same nested structure of lists/tuples or be numbers")


