def lucky_num(n):
    # Start with the list of odd numbers starting from 1
    numbers = list(range(1, 2 * n * 10, 2))  # overshoot to ensure enough numbers

    idx = 1
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number, counting from 1-based indexing
        # but skipping the number at position idx itself
        # The positions to remove are multiples of step (1-based)
        # so indices step-1, 2*step-1, 3*step-1, ...
        # Adjust indices as list is 0-based and we remove in-place
        del numbers[step - 1::step]
        idx += 1
        if len(numbers) >= n:
            # If we have at least n numbers, we can stop early
            # but to be safe, continue until no more removals
            pass

    return numbers[:n]


