def dif_Square(n: int) -> bool:
    # A number n can be expressed as difference of squares:
    # n = a^2 - b^2 = (a-b)(a+b)
    # Let x = a-b, y = a+b, then n = x*y and both x,y are integers.
    # Also, a = (x+y)/2, b = (y - x)/2 must be integers, so x and y must be both even or both odd.
    # So n can be expressed as difference of squares iff n has at least one factorization n = x*y
    # where x and y have the same parity.
    # We check all factor pairs.
    if n == 0:
        return True  # 0 = 0^2 - 0^2 trivially
    abs_n = abs(n)
    for x in range(1, int(abs_n**0.5) + 1):
        if abs_n % x == 0:
            y = abs_n // x
            # check both (x,y) and (-x,-y) pairs, parity same check is parity(x)==parity(y)
            if (x % 2) == (y % 2):
                # For n positive, (a,b) = ((x+y)/2, (y-x)/2)
                # For n negative, we can consider (x,-y) or (-x,y), but parity condition remains same
                # Since parity condition holds, difference of squares representation exists.
                return True
    return False


