def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)

    # Helper to check if all digits are '9'
    if all(ch == '9' for ch in s):
        # The next palindrome greater than n would be 10...01 with (length+1) digits
        return int('1' + ('0' * (length - 1)) + '1')

    def make_palindrome(left: str, odd_length: bool) -> int:
        if odd_length:
            return int(left + left[-2::-1])
        else:
            return int(left + left[::-1])

    odd = (length % 2 != 0)
    mid = length // 2

    if odd:
        left = s[:mid+1]
    else:
        left = s[:mid]

    pal = make_palindrome(left, odd)
    if pal > n:
        return pal

    # Increment the left (including middle if odd)
    left_num = int(left) + 1
    left_str = str(left_num)
    # If length of left_str increased, e.g. 999 + 1 = 1000, then palindrome length increases by 1
    if len(left_str) > len(left):
        # This means palindrome length increased (e.g. from 999 -> 1000)
        # So palindrome is now of length+1 and is '1' + zeros + '1'
        return int('1' + ('0' * (length - 1)) + '1')

    return make_palindrome(left_str, odd)


