def find_solution(a: int, b: int, n: int):
    # We want non-negative integers x, y such that a*x + b*y = n.
    # Try all possible x from 0 up to n//a (if a > 0)
    # and check if corresponding y = (n - a*x)/b is a non-negative integer.
    # Handle zero or negative a or b carefully.

    # If both a and b are zero:
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None

    # If a == 0:
    if a == 0:
        if b == 0:
            return None
        if (n % b == 0) and (n // b >= 0):
            return (0, n // b)
        return None

    # If b == 0:
    if b == 0:
        if (n % a == 0) and (n // a >= 0):
            return (n // a, 0)
        return None

    # Now a and b are both nonzero (could be positive or negative)
    # But since the problem is about non-negative x,y, it only makes sense
    # to iterate x from 0 upwards and check y.
    # Let's try to avoid infinite loops:
    # We can find the range of x:
    # If a > 0, x in [0, n//a] (if n>=0), else no solutions with non-negative x.
    # If a < 0, then a*x ≤ 0 for x≥0, so a*x ≤ 0.
    # Since n = a*x + b*y ≥ 0, and a*x ≤ 0, b*y ≥ n - a*x ≥ n.
    # So we can try x=0 up to some reasonable upper bound.

    # To handle negative a or b, we find the range of x for which y can be non-negative integer.

    # We'll iterate x in [0, max_x], where max_x is chosen so that y might be non-negative.
    # y = (n - a*x)/b >= 0 => n - a*x and b must have same sign.
    # So:
    # If b > 0:
    #   y >= 0 => n - a*x >= 0 => x <= n/a if a>0 else x >= n/a if a<0
    #   Since x ≥ 0, we consider these bounds carefully.
    # If b < 0:
    #   y >= 0 => n - a*x <= 0 => x >= n/a if a>0 else x <= n/a if a<0

    # We'll compute candidate x values from 0 up to some upper bound.

    # To avoid floating point, use integer division carefully.

    # Determine x range:

    from math import ceil, floor

    def safe_div_floor(num, denom):
        # floor division that works for negative numbers correctly
        if denom == 0:
            return None
        return num // denom if (num * denom) >=0 else (num - (denom + (1 if denom > 0 else -1))) // denom

    def safe_div_ceil(num, denom):
        # ceil division that works for negative numbers correctly
        if denom == 0:
            return None
        q, r = divmod(num, denom)
        if r == 0:
            return q
        return q + 1 if (num * denom) > 0 else q

    # Compute x_min and x_max for iteration

    x_candidates = []

    # We want to find all x >= 0 such that y = (n - a*x)/b is integer and y >= 0.

    # Let's find the x range that can produce y >= 0:

    # From y >= 0:
    # b*y = n - a*x
    # So if b>0: n - a*x >= 0 => a*x <= n
    # if b<0: n - a*x <= 0 => a*x >= n

    # Let's get possible bounds on x:

    if b > 0:
        # a*x <= n
        # If a > 0: x <= n//a
        # If a < 0: x >= ceil(n/a)
        if a > 0:
            x_max = n // a if n >= 0 else -1  # if n<0 no x>=0 satisfies x <= n//a
            x_min = 0
            if x_max < 0:
                return None
        else:
            # a < 0
            x_min = ceil(n / a)
            if x_min < 0:
                x_min = 0
            x_max = 10**9  # large number to avoid infinite, but we will break early.
    else:
        # b < 0
        # n - a*x <= 0 => a*x >= n
        # If a > 0: x >= ceil(n/a)
        # If a < 0: x <= floor(n/a)
        if a > 0:
            x_min = ceil(n / a)
            if x_min < 0:
                x_min = 0
            x_max = 10**9
        else:
            x_max = n // a if n >= 0 else -1
            x_min = 0
            if x_max < 0:
                return None

    # We'll iterate from x_min to x_max (inclusive), but only for x >= 0

    # To avoid infinite loop, cap x_max to a reasonable number for search:

    max_search = 10**7
    if x_max > max_search:
        x_max = max_search

    for x in range(x_min, x_max + 1):
        if x < 0:
            continue
        numerator = n - a * x
        if numerator % b == 0:
            y = numerator // b
            if y >= 0:
                return (x, y)

    return None


