def get_total_number_of_sequences(n: int, k: int) -> int:
    if n == 0:
        return 0
    if n == 1:
        return k
    # For sequences of length n with k possible elements, where the next element cannot be the same as the previous one:
    # First element: k choices
    # Each subsequent element: k-1 choices (cannot be the same as previous)
    return k * (k - 1) ** (n - 1)


