def smallest_missing(arr, low, high):
    if low > high or low < 0 or high >= len(arr):
        return None

    # The missing number must be within arr[low] .. arr[high] or arr[high] + 1 if none missing.
    start = arr[low]
    end = arr[high]

    # Binary search for smallest missing number in arr[low:high+1]
    # The idea: for a sorted array with distinct integers, if arr[mid] == start + (mid - low),
    # then no missing number up to mid, else missing number is at or before mid.

    left, right = low, high
    while left <= right:
        mid = (left + right) // 2
        expected = start + (mid - low)
        if arr[mid] == expected:
            left = mid + 1
        else:
            right = mid - 1

    # left is the insertion point for the missing number
    missing = start + (left - low)
    # If missing > end, all present, return end + 1 (which is high + 1 per user answer)
    if missing > end:
        return end + 1
    return missing


