def find_Max(arr, start, end):
    if start == end:
        return arr[start]
    if arr[start] < arr[end]:
        return arr[end]
    mid = (start + end) // 2
    if arr[mid] > arr[mid + 1]:
        return arr[mid]
    if arr[mid] >= arr[start]:
        return find_Max(arr, mid + 1, end)
    else:
        return find_Max(arr, start, mid)


