def dif_Square(n: int) -> bool:
    # A number n can be represented as difference of two squares x² - y² = n
    # which factors as (x-y)(x+y) = n.
    # Since x,y are integers, x-y and x+y must be integers.
    #
    # Let a = x-y and b = x+y. Then n = a*b.
    # Also, x = (a+b)/2, y = (b - a)/2 must be integers, so (a+b) and (b-a) are even,
    # meaning a and b have the same parity (both even or both odd).
    #
    # So n can be written as a product of two integers a and b, both having the same parity.
    #
    # Therefore, n can be expressed as difference of squares iff there exists a factorization n = a*b
    # where a and b have the same parity.
    #
    # Special case: n=0 can be represented as 0² - 0² = 0, so return True.
    #
    # To decide quickly:
    # - If n is odd, its factors must be odd*odd (since odd*even or even*odd is even).
    #   So odd n can always be represented (try a=1, b=n).
    # - If n is divisible by 4, then factors (a,b) can be both even.
    #   So n divisible by 4 can be represented.
    # - If n is even but not divisible by 4 (i.e., n % 4 == 2), then no factorization into two same parity numbers.
    #
    # Thus, the condition is: n % 4 != 2.
    #
    # This includes negative numbers as well.

    return n % 4 != 2


