def find_solution(a, b, n):
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else 'No solution'
    if a == 0:
        if n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return 'No solution'
    for x in range(0, abs(n) + 1 if a > 0 else abs(n) * 2 + 1):
        remainder = n - a * x
        if b == 0:
            if remainder == 0:
                return (x, 0)
            else:
                continue
        if remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return (x, y)
    return 'No solution'


