def find_Max(arr):
    if not arr:
        return None
    left, right = 0, len(arr) - 1
    # If array is not rotated (sorted ascending), max is last element
    if arr[left] < arr[right]:
        return arr[right]
    # Binary search for max element
    while left < right:
        mid = (left + right) // 2
        # If mid element is greater than right, max must be mid or in right half
        if arr[mid] > arr[right]:
            left = mid + 1
        else:
            right = mid
    # After loop, left points to smallest element; max is element before it
    return arr[left - 1] if left > 0 else arr[-1]


