def lucky_num(n):
    numbers = list(range(1, 2 * n * 10))  # overshoot to ensure enough lucky numbers
    idx = 1
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # remove every step-th number starting from the step-th index (1-based)
        del numbers[step - 1::step]
        idx += 1
        if len(numbers) >= n:
            # No early stopping here, we must complete the sieve process
            # but since the list shrinks, we can stop if step > len(numbers)
            continue
        else:
            break
    return numbers[:n]


