def dif_Square(n: int) -> bool:
    # A number n can be expressed as a difference of two squares if and only if n is NOT
    # congruent to 2 mod 4.
    # This is because:
    # (a^2 - b^2) = (a-b)(a+b)
    # Both (a-b) and (a+b) have same parity,
    # so their product cannot be 2 modulo 4.
    return n % 4 != 2


