def next_smallest_palindrome(n: int) -> int:
    n += 1  # strictly greater than n
    s = str(n)
    length = len(s)

    while True:
        half_len = (length + 1) // 2
        left_half = s[:half_len]

        # Construct palindrome by mirroring left half to right
        if length % 2 == 0:
            pal = left_half + left_half[::-1]
        else:
            pal = left_half + left_half[:-1][::-1]

        pal_num = int(pal)
        if pal_num >= n:
            return pal_num

        # Increment left half and rebuild palindrome
        left_num = int(left_half) + 1
        left_half = str(left_num)

        # If increment caused length increase, means palindrome length increases by 1 or 2
        if len(left_half) > half_len:
            length += 1
            n = int('1' + ('0' * (length - 1)))
            s = str(n)
        else:
            s = left_half + s[half_len:]


