def find_solution(a, b, n):
    if b == 0:
        # If b is 0, equation is a*x = n, check if n is divisible by a
        if a != 0 and n % a == 0 and n // a >= 0:
            x = n // a
            y = 0
            return ('x = ', x, ', y = ', y)
        else:
            return "No solution"
    for x in range(0, n + 1):
        remainder = n - a * x
        if b == 0:
            # Avoid division by zero, handled above, but here for completeness
            continue
        if remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return ('x = ', x, ', y = ', y)
    return "No solution"


