def remove_column(data, key_or_indices):
    """
    Remove dictionary entries by key and remove elements by index from each inner list when given a list of lists of indices.

    Parameters:
    - data: nested structure of dicts and lists
    - key_or_indices: either a single key (str) to remove from dicts,
                      or a list of lists of indices to remove from inner lists

    Returns:
    A new nested structure with the specified removals applied.
    """
    def remove_from_dict(d, key):
        # Remove key from dict and recurse into values
        new_d = {}
        for k, v in d.items():
            if k != key:
                new_d[k] = remove_column(v, key_or_indices)
        return new_d

    def remove_from_list(lst):
        # If key_or_indices is a list of lists, try to remove from this list using corresponding indices
        # We remove elements at indices given for this list, if any
        # Then recurse into elements
        # Because the function doesn't get a mapping of list to indices, 
        # we must apply the same indices to every list inside (most standard)
        # But user said "support removing elements by index from each inner list when given a list of lists" - so key_or_indices is a list of lists
        # So:
        #   - If key_or_indices is list of lists, then the outer list corresponds to the levels of nesting of lists?
        #   - The user said "support removing elements by index from each inner list when given a list of lists"
        # This is ambiguous about how to match indices to lists.
        # The least surprising: if key_or_indices is list of lists, we remove from each list at the same nesting level the indices in the corresponding list.
        # So we track depth of list nesting to apply correct indices.
        # To do that, we implement a helper with current depth.

        # But the signature only has data and key_or_indices, no depth.
        # So implement a helper with depth param.

        return remove_from_list_depth(lst, 0)  # start at depth 0

    def remove_from_list_depth(lst, depth):
        if not isinstance(lst, list):
            return remove_column(lst, key_or_indices)

        # Determine indices to remove at this depth if key_or_indices is list of lists
        indices_to_remove = set()
        if isinstance(key_or_indices, list):
            # check if key_or_indices is list of lists
            if all(isinstance(sub, list) for sub in key_or_indices):
                if depth < len(key_or_indices):
                    indices_to_remove = set(key_or_indices[depth])
            # else key_or_indices is a str or something else, no removal by index here

        new_lst = []
        for i, item in enumerate(lst):
            if i in indices_to_remove:
                continue
            new_lst.append(remove_from_list_depth(item, depth + 1))
        return new_lst

    # Main dispatcher
    if isinstance(data, Mapping):
        if isinstance(key_or_indices, str):
            return remove_from_dict(data, key_or_indices)
        else:
            # no key removal if key_or_indices is indices
            # still recurse normally
            return {k: remove_column(v, key_or_indices) for k, v in data.items()}
    elif isinstance(data, list):
        if isinstance(key_or_indices, str):
            # no removal by index, just recurse
            return [remove_column(item, key_or_indices) for item in data]
        else:
            # key_or_indices is list of lists of indices
            return remove_from_list(data)
    else:
        # base case: not dict or list, return as is
        return data


