def permute_string(s):
    def helper(prefix, remainder):
        if not remainder:
            return [prefix]
        result = []
        for i, ch in enumerate(remainder):
            # Insert ch at the front and recurse on remainder without ch
            # But to avoid duplicates, skip if ch has appeared before at this recursion level
            if i > 0 and remainder[i] == remainder[i-1]:
                continue
            result.extend(helper(prefix + ch, remainder[:i] + remainder[i+1:]))
        return result

    # To avoid duplicates by skipping repeated chars at each recursion level,
    # sort the string so duplicates are adjacent
    return helper("", ''.join(sorted(s)))


