def lucky_num(n):
    # Start with a list of odd numbers starting from 1
    # We'll generate more than n initially to ensure we get at least n lucky numbers
    # It's known lucky numbers are infinite but sparse,
    # so start with an upper bound and increase if needed.
    # For simplicity, start with a list of length 3*n (heuristic).

    length = 3 * n
    numbers = list(range(1, 2 * length, 2))  # odd numbers from 1 upwards

    idx = 1  # index in numbers, 0-based; the first sieve step uses numbers[1]
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number starting from step-1 index (0-based)
        del numbers[step-1::step]
        idx += 1
        if len(numbers) >= n:
            break

    # If after sieving length < n, increase length and repeat
    while len(numbers) < n:
        length *= 2
        numbers = list(range(1, 2 * length, 2))
        idx = 1
        while idx < len(numbers):
            step = numbers[idx]
            if step > len(numbers):
                break
            del numbers[step-1::step]
            idx += 1

    return numbers[:n]


