def get_noOfways(n: int) -> int:
    # Number of ways to tile a 2xN board with 2x1 dominoes is the (n+1)th Fibonacci number
    # with base cases adjusted so that get_noOfways(2) == 1.
    # The sequence:
    # n: 1 2 3  4  5  ...
    # ways:1 1 2  3  5  ...
    if n <= 2:
        return 1
    a, b = 1, 1
    for _ in range(3, n + 1):
        a, b = b, a + b
    return b


