def compute_Last_Digit(a: int, b: int) -> int:
    # factorial(b) // factorial(a) = (a+1) * (a+2) * ... * b
    # We want the last digit of this product in base 10.

    product = 1
    for x in range(a + 1, b + 1):
        product *= x
        product %= 10  # keep only last digit to avoid large number

    return product


