def sort_sublists(collection):
    result = []
    for subseq in collection:
        sorted_subseq = sorted(subseq)
        if isinstance(subseq, tuple):
            result.append(tuple(sorted_subseq))
        elif isinstance(subseq, list):
            result.append(sorted_subseq)
        else:
            # For other sequence types, try to preserve type by calling type on sorted result
            try:
                result.append(type(subseq)(sorted_subseq))
            except Exception:
                # Fallback to list if type cannot be constructed from iterable
                result.append(sorted_subseq)
    return result


