def next_power_of_2(value: int) -> int:
    if value <= 1:
        return 1
    # If value is already a power of two, return it
    if (value & (value - 1)) == 0:
        return value
    # Otherwise, find next power of two
    power = 1
    while power < value:
        power <<= 1
    return power


