def get_total_number_of_sequences(N: int, K: int) -> int:
    from functools import lru_cache

    @lru_cache(None)
    def count_sequences(prev: int, length: int) -> int:
        if length == K:
            return 1
        total = 0
        start = prev * 2
        for next_val in range(start, N + 1):
            total += count_sequences(next_val, length + 1)
        return total

    total_sequences = 0
    for first in range(1, N + 1):
        total_sequences += count_sequences(first, 1)
    return total_sequences


