from typing import List, Tuple, Union

def remove_column(collection: List[Union[List, Tuple]], position: int) -> List[Union[List, Tuple]]:
    result = []
    for inner in collection:
        if not isinstance(inner, (list, tuple)):
            # According to spec, only lists or tuples are supported as inner types,
            # so we can skip or keep as-is. The spec says only support lists or tuples,
            # so we assume input is well-formed.
            result.append(inner)
            continue

        if 0 <= position < len(inner):
            new_inner = inner[:position] + inner[position+1:]
        else:
            new_inner = inner

        # Preserve the original inner type
        if isinstance(inner, tuple):
            new_inner = tuple(new_inner)
        else:
            new_inner = list(new_inner)

        result.append(new_inner)

    return result


