import re

def capital_words_spaces(text: str) -> str:
    # Insert a space before each capital letter that starts a new word,
    # except if it's the first character of the string.
    # Also, do not insert space if the capital letter is immediately after a space (already separated).
    # The rule: For every capital letter preceded by a non-space and non-start, insert a space.

    # Use regex to find capital letters preceded by a non-space character (not start of string)
    return re.sub(r'(?<!^)(?<!\s)([A-Z])', r' \1', text)


