def sum_column(grouped_data, group_keys, column):
    """
    Sum the values of `column` in the selected part of grouped_data.

    Parameters:
    - grouped_data: dict mapping group keys (tuples or single keys) to lists of dicts (records).
    - group_keys: a single group key or an iterable of group keys to select groups.
    - column: the column name (string) whose values to sum in the selected group(s).

    Returns:
    - If group_keys is a single key, returns the sum of column values in that group (0 if group missing).
    - If group_keys is an iterable of keys, returns a dict mapping each key to the sum of column values in that group.
      Missing groups yield sum 0.
    """
    # Normalize group_keys into a list if it's not iterable (except str)
    if isinstance(group_keys, (str, bytes)) or not hasattr(group_keys, '__iter__'):
        group_keys = [group_keys]

    result = {}
    for key in group_keys:
        records = grouped_data.get(key, [])
        total = 0
        for record in records:
            val = record.get(column, 0)
            if isinstance(val, (int, float)):
                total += val
            else:
                # If the value is not numeric, ignore or treat as 0
                try:
                    total += float(val)
                except (ValueError, TypeError):
                    pass
        result[key] = total

    # Return single sum if only one key requested
    if len(result) == 1:
        return next(iter(result.values()))
    return result


