from collections import Counter
from typing import Sequence, List

def substract_elements(groups1: Sequence[Sequence[int]], groups2: Sequence[Sequence[int]]) -> List[List[int]]:
    result = []
    for g1, g2 in zip(groups1, groups2):
        c1 = Counter(g1)
        c2 = Counter(g2)
        diff = c1 - c2  # subtract counts, only positive remain
        group_result = []
        for num, count in diff.items():
            group_result.extend([num] * count)
        result.append(group_result)
    return result


