def lucky_num(n):
    # Generate the first n lucky numbers using the sieve of lucky numbers.
    # The lucky numbers start with [1, 3, 7, 9, 13, 15, ...]
    # The sieve works by:
    # 1. Start with a list of odd numbers starting from 1.
    # 2. The second number in the list is the step to remove elements.
    # 3. Remove every step-th number from the list (1-based indexing).
    # 4. Repeat using the next number in the list as the next step.
    # 5. Continue until no more removal is possible or we have enough lucky numbers.

    # Since lucky numbers become sparse, we start with a sufficiently large list and increase if needed.
    def generate_lucky_numbers(limit):
        nums = list(range(1, limit + 1, 2))  # Start with odd numbers only
        idx = 1  # Start from second element (index 1)
        while idx < len(nums):
            step = nums[idx]
            if step > len(nums):
                break
            # Remove every step-th element (1-based indexing)
            # To do this correctly: remove nums at positions step-1, 2*step-1, 3*step-1, etc.
            # But since after deletions indices change, better to rebuild the list filtering out those positions.
            nums = [num for i, num in enumerate(nums) if (i + 1) % step != 0]
            idx += 1
        return nums

    # heuristic initial size:
    size = max(100, n * 50)  # Start larger for safety
    while True:
        lucky_list = generate_lucky_numbers(size)
        if len(lucky_list) >= n:
            return lucky_list[:n]
        size *= 2


