def compute_Last_Digit(a: int, b: int) -> int:
    if a > b:
        return 0
    if a == b:
        return 1
    last_digit = 1
    for num in range(a + 1, b + 1):
        last_digit = (last_digit * (num % 10)) % 10
        # If last_digit becomes 0, we can break early
        if last_digit == 0:
            break
    return last_digit


