def dif_Square(n: int) -> bool:
    # A number n can be represented as a difference of two squares:
    # n = a^2 - b^2 = (a+b)(a-b)
    #
    # For integer a,b, (a+b) and (a-b) are integers of the same parity (both even or both odd).
    # So n can be represented as difference of squares iff n is NOT congruent to 2 mod 4.
    #
    # Explanation:
    # Squares mod 4 are 0 or 1.
    # Difference of squares mod 4 can be 0, 1, or 3, but never 2.
    #
    # Therefore, return False if n % 4 == 2, else True.

    return n % 4 != 2


