def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # Helper to check if all digits are 9
    if all(ch == '9' for ch in s):
        # Next palindrome after 999...9 is 100...001
        return num + 2  # e.g. 9 -> 11, 99 -> 101, 999 -> 1001

    def make_palindrome(left: str, middle: str, odd_len: bool) -> int:
        if odd_len:
            return int(left + middle + left[::-1])
        else:
            return int(left + left[::-1])

    odd_len = (length % 2 != 0)
    mid_index = length // 2

    if odd_len:
        left = s[:mid_index]
        middle = s[mid_index]
        right = s[mid_index+1:]
    else:
        left = s[:mid_index]
        middle = ''
        right = s[mid_index:]

    # Construct palindrome by mirroring left + middle
    palindrome = make_palindrome(left, middle, odd_len)

    if palindrome > num:
        return palindrome

    # If palindrome <= num, we need to increment the middle part and mirror again
    if odd_len:
        # Increment middle digit plus left part as a combined integer
        left_middle_num = int(left + middle)
        left_middle_num += 1
        left_middle_str = str(left_middle_num)
        # If length changed due to carry (e.g. 999 -> 1000), adjust accordingly
        if len(left_middle_str) > len(left) + 1:
            # This means palindrome length increased by 1
            return int('1' + ('0' * (length - 1)) + '1')
        new_left = left_middle_str[:-1]
        new_middle = left_middle_str[-1]
        return make_palindrome(new_left, new_middle, True)
    else:
        # Even length: increment left part and mirror
        left_num = int(left)
        left_num += 1
        left_str = str(left_num)
        if len(left_str) > len(left):
            # Length increased, e.g. 99 -> 100, palindrome grows by 1 digit
            return int('1' + ('0' * (length -1)) + '1')
        return make_palindrome(left_str, '', False)


