def find_solution(a, b, n):
    # We want nonnegative integers x, y such that a*x + b*y = n.
    # First, check if a and b are zero. If both zero, no solution unless n=0.
    if a == 0 and b == 0:
        return (0,0) if n == 0 else None
    # If one of a or b is zero:
    if a == 0:
        if n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return None
    if b == 0:
        if n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return None

    # Now both a and b are nonzero.
    # Use extended Euclidean algorithm to find one solution to a*x + b*y = gcd(a,b)
    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        else:
            g, s, t = extended_gcd(y, x % y)
            return (g, t, s - (x // y) * t)

    g, x0, y0 = extended_gcd(abs(a), abs(b))
    # Check if n is multiple of g
    if n % g != 0:
        return None

    # Scale the solution
    x0 *= n // g
    y0 *= n // g

    # Adjust signs according to signs of a and b
    if a < 0:
        x0 = -x0
    if b < 0:
        y0 = -y0

    # General solution:
    # x = x0 + k*(b/g)
    # y = y0 - k*(a/g)
    # We want x >= 0 and y >= 0

    # Let:
    bg = b // g
    ag = a // g

    # Find k so that x >= 0:
    # x0 + k*bg >= 0 => k >= -x0/bg if bg > 0 else k <= -x0/bg
    # Similarly for y:
    # y0 - k*ag >= 0 => k <= y0/ag if ag > 0 else k >= y0/ag

    # We want to find integer k such that both inequalities hold.

    from math import ceil, floor

    if bg > 0:
        k_min = ceil(-x0 / bg)
    else:
        k_min = -float('inf')  # no lower bound from x

    if bg < 0:
        k_max = floor(-x0 / bg)
    else:
        k_max = float('inf')  # no upper bound from x

    if ag > 0:
        k_max = min(k_max, floor(y0 / ag))
    else:
        k_min = max(k_min, ceil(y0 / ag))

    # Now check if there exists k in [k_min, k_max]
    if k_min > k_max:
        return None

    # Choose k = k_min (smallest integer that satisfies)
    k = k_min

    x = x0 + k * bg
    y = y0 - k * ag

    if x < 0 or y < 0:
        return None

    return (x, y)


