def lucky_num(n):
    # Generate lucky numbers using the standard sieve method
    # Start with the list of natural numbers starting from 1
    numbers = list(range(1, 2*n*10))  # overshoot length to ensure enough lucky numbers

    idx = 1  # start from the second number (index 1)
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number starting from index step-1 (0-based)
        del numbers[step-1::step]
        idx += 1
        if len(numbers) >= n:
            # We have at least n lucky numbers, can stop early
            # but continue to keep sieve correct to get exact first n lucky numbers
            # Actually if we stop early, the list might not be fully sieved.
            # So better to sieve fully until the step number exceeds length.
            pass

    return numbers[:n]


