def get_noOfways(n, m):
    if m != 2:
        return 0  # As per the task, we only handle 2 x n boards
    if n == 0:
        return 1
    if n == 1:
        return 1
    a, b = 1, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b


